public:
    unsigned int FontHeight;
    int MinChar;
    int MaxChar;
    GlyphBank GlyphBanks[1024];

    CStaticFontBank()
        : FontHeight(9), MinChar(10), MaxChar(0x0101)
    {
        for (unsigned int i = 0; i < 1024; ++i) {
            GlyphBanks[i].FirstGlyph = 0;
            GlyphBanks[i].NoGlyphs = 0;
            GlyphBanks[i].Glyphs = 0;
